def max_fill(grid, capacity):
    def dfs(i, j, count):
        if i < 0 or j < 0 or i >= len(grid) or j >= len(grid[0]) or grid[i][j] == 0:
            return count
        grid[i][j] = 0
        count += dfs(i+1, j, 0) + dfs(i-1, j, 0) + dfs(i, j+1, 0) + dfs(i, j-1, 0) + 1
        return count

    return dfs(0, 0, 0)
```

